const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const dateStr = '2017-06-21';
  const start = ee.Date(dateStr);
  const end = start.advance(1, 'day');

  // Locations (approx city centers), buffered to 3 km for adequate pixels at 1 km scale
  const needlesPt = ee.Geometry.Point([-114.614, 34.848]);
  const phoenixPt = ee.Geometry.Point([-112.074, 33.448]);
  const needlesGeom = needlesPt.buffer(3000);
  const phoenixGeom = phoenixPt.buffer(3000);

  const scalePrimary = 1000;
  const scaleFallback = 3000;

  function maskMODISDay(img) {
    const lst = img.select('LST_Day_1km');
    const qc = img.select('QC_Day');
    const goodQA = qc.bitwiseAnd(3).lte(1); // bits 0-1 <= 1 (best or good)
    const validLST = lst.gt(0);
    return img.updateMask(goodQA.and(validLST));
  }

  async function statsForCollection(collectionId, geom, scale) {
    const col = ee.ImageCollection(collectionId).filterDate(start, end).filterBounds(geom);
    const size = await col.size().getInfo();
    if (size === 0) {
      return {exists: false};
    }
    const img = maskMODISDay(col.mosaic());
    // Total 1 km pixels in geometry (approximate), independent of mask
    let totalCount = await ee.Image.constant(1).rename('one')
      .reduceRegion({reducer: ee.Reducer.count(), geometry: geom, scale: scale, maxPixels: 1e9, bestEffort: true})
      .get('one').getInfo();
    if (!totalCount || totalCount === 0) {
      // retry with coarser scale
      totalCount = await ee.Image.constant(1).rename('one')
        .reduceRegion({reducer: ee.Reducer.count(), geometry: geom, scale: scaleFallback, maxPixels: 1e9, bestEffort: true})
        .get('one').getInfo();
    }
    const validCount = await img.select('LST_Day_1km')
      .reduceRegion({reducer: ee.Reducer.count(), geometry: geom, scale: scale, maxPixels: 1e9, bestEffort: true})
      .get('LST_Day_1km').getInfo();
    const meanDN = await img.select('LST_Day_1km')
      .reduceRegion({reducer: ee.Reducer.mean(), geometry: geom, scale: scale, maxPixels: 1e9, bestEffort: true})
      .get('LST_Day_1km').getInfo();
    let meanC = null;
    if (meanDN !== null && meanDN !== undefined) {
      meanC = meanDN * 0.02 - 273.15; // scale to Kelvin, then to Celsius
    }
    const cloudPct = (totalCount && totalCount > 0 && validCount !== null) ? (100 * (1 - validCount / totalCount)) : null;
    return {
      exists: true,
      images: size,
      totalCount: totalCount || 0,
      validCount: validCount || 0,
      cloudPct: cloudPct,
      meanC: meanC
    };
  }

  async function getCityLST(geom, cityName) {
    // Try Terra first
    let s = await statsForCollection('MODIS/006/MOD11A1', geom, scalePrimary);
    if (s.exists && s.validCount > 0 && s.meanC !== null) {
      return {...s, source: 'Terra MOD11A1'};
    }
    // Fallback to Aqua if Terra invalid or 0 valid pixels
    let a = await statsForCollection('MODIS/006/MYD11A1', geom, scalePrimary);
    if (a.exists && a.validCount > 0 && a.meanC !== null) {
      return {...a, source: 'Aqua MYD11A1'};
    }
    // Determine failure type
    const terraExists = s.exists;
    const aquaExists = a.exists;
    if (!terraExists && !aquaExists) {
      return {failure: 'C1'};
    }
    if ((terraExists && (s.validCount === 0 || s.meanC === null)) &&
        (aquaExists && (a.validCount === 0 || a.meanC === null))) {
      return {failure: 'C2'};
    }
    return {failure: 'C3'};
  }

  try {
    console.log(`Date: ${dateStr}`);
    const needlesRes = await getCityLST(needlesGeom, 'Needles, CA');
    const phoenixRes = await getCityLST(phoenixGeom, 'Phoenix, AZ');

    // Handle failures
    if (needlesRes.failure || phoenixRes.failure) {
      const failurePriority = (tag) => ({'C1':1,'C2':2,'C3':3}[tag]);
      const failures = [];
      if (needlesRes.failure) failures.push(needlesRes.failure);
      if (phoenixRes.failure) failures.push(phoenixRes.failure);
      const finalFail = failures.sort((a,b)=>failurePriority(a)-failurePriority(b))[0];
      console.log(`Needles status: ${needlesRes.failure || 'OK'}`);
      console.log(`Phoenix status: ${phoenixRes.failure || 'OK'}`);
      if (finalFail === 'C1') {
        console.log('C1: Empty Collection (No images found in date/location for one or both comparison points).');
      } else if (finalFail === 'C2') {
        console.log('C2: No Valid Pixels (Images exist, but after cloud masking/processing, 0 pixels remain).');
      } else {
        console.log('C3: Calculation Failure (Result is None, NaN, or invalid).');
      }
      return;
    }

    // Validate plausible temperature ranges
    function invalid(val) {
      return (val === null || isNaN(val) || val < -100 || val > 100);
    }
    if (invalid(needlesRes.meanC) || invalid(phoenixRes.meanC)) {
      console.log('C3: Calculation Failure (Result is None, NaN, or invalid).');
      return;
    }

    const nCloud = (needlesRes.cloudPct !== null) ? needlesRes.cloudPct.toFixed(1) : 'NA';
    const pCloud = (phoenixRes.cloudPct !== null) ? phoenixRes.cloudPct.toFixed(1) : 'NA';

    console.log(`Needles Source: ${needlesRes.source} (images: ${needlesRes.images}), Valid px: ${needlesRes.validCount}/${needlesRes.totalCount} (cloud: ${nCloud}%), LST_C: ${needlesRes.meanC.toFixed(2)}`);
    console.log(`Phoenix  Source: ${phoenixRes.source} (images: ${phoenixRes.images}), Valid px: ${phoenixRes.validCount}/${phoenixRes.totalCount} (cloud: ${pCloud}%), LST_C: ${phoenixRes.meanC.toFixed(2)}`);

    const answer = (needlesRes.meanC > phoenixRes.meanC) ? 'A: Yes' : 'B: No';
    console.log(answer);
  } catch (err) {
    console.error('Error:', err);
    console.log('D: Processing/Code Error');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
